pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = c.owner();
    }

    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Ensure target is not the zero address to avoid call issues
        vm.assume(target != address(0));

        // Bound value to a reasonable range (e.g., <= 100 ether)
        value = bound(value, 0, 100 ether);

        // Fund the contract with enough balance for the call
        vm.deal(address(c), value);

        // Record owner's balance before the call
        uint256 ownerBalanceBefore = owner.balance;

        // Perform the sendMoney call (onlyOwner, so call as owner)
        vm.prank(owner);
        // Use try/catch to handle potential revert
        bool reverted = false;
        try c.sendMoney(target, value, data) {
            // success
        } catch {
            reverted = true;
        }

        // The rule: If the call did not revert, the owner's balance increases by exactly value
        if (!reverted) {
            uint256 ownerBalanceAfter = owner.balance;
            assertTrue(ownerBalanceAfter == ownerBalanceBefore + value, "Owner balance did not increase by sent value");
        } else {
            // If it reverted, we consider the property vacuously true
            assertTrue(true);
        }
    }
}
